use crate::{Runtime,Value,EnvId,JsResult,JsError,PropertyKey,KeyInput,ObjectKind};
fn number_bits(value:Value)->u64{let Value::Number(n)=value else{panic!("expected number, got {value:?}")};n.to_bits()}
fn getter(rt:&mut Runtime,_:Value,_:&[Value],env:EnvId)->JsResult<Value>{let Value::Number(n)=rt.lookup(env,"hits")?else{panic!()};rt.assign(env,"hits",Value::Number(n+1.0),false)?;Ok(Value::Number(91.0))}
fn setter(rt:&mut Runtime,_:Value,args:&[Value],env:EnvId)->JsResult<Value>{rt.assign(env,"written",args[0],false)?;Ok(Value::Undefined)}
fn mutate_key(rt:&mut Runtime,_:Value,_:&[Value],env:EnvId)->JsResult<Value>{let array=rt.lookup(env,"array")?;let Value::Number(mode)=rt.lookup(env,"mode")?else{panic!()};let key=rt.string("0");match mode as u8{0=>{rt.set(array,key,Value::Number(-0.0),true)?;},1=>{let f=rt.make_closure(getter,env,0,"getter");rt.define_accessor(array,key,Some(f),None,true,true)?;},2=>{rt.delete(array,key,true)?;let proto=rt.object();let f=rt.make_closure(getter,env,0,"getter");rt.define_accessor(proto,key,Some(f),None,true,true)?;rt.set_prototype(array,proto)?;},3=>{let length=rt.string("length");rt.set(array,length,Value::Number(0.0),true)?;},4=>{return Err(JsError::Throw(Value::Number(777.0)))},_=>{rt.diagnostics.enabled=true;}}Ok(key)}
#[test]fn raw_numbers_read_and_write_match_reference_paths_for_all_three_key_kinds(){for enabled in[false,true]{let mut rt=Runtime::new();rt.primary_numeric_access_enabled=enabled;rt.diagnostics.enabled=false;let array=rt.array(&[Some(Value::Number(1.0)),Some(Value::Number(2.0)),Some(Value::Number(3.0)),Some(Value::Number(4.0))]);for bits in[0u64,1,0x8000000000000000,0x7ff0000000000000,0xfff0000000000000,0x7ff0000000000042,0xfff8000000001234,u64::MAX]{for index in 0..4{let number=Value::Number(f64::from_bits(bits));let key=rt.string(&index.to_string());rt.set(array,key,number,true).unwrap();let id=rt.object_id(array).unwrap();assert!(matches!(rt.objects[id.0].kind,ObjectKind::Array{primary_numeric:true,..}));assert_eq!(number_bits(rt.get(array,key).unwrap()),bits);assert_eq!(number_bits(rt.get(array,Value::Number(index as f64)).unwrap()),bits);let prepared=PropertyKey(rt.intern(&index.to_string()));assert_eq!(number_bits(rt.get(array,prepared).unwrap()),bits);}}}}
#[test]fn coercion_mutates_or_deopts_before_fresh_read_and_preserves_throw_order(){for enabled in[false,true]{for mode in 0..5{let mut rt=Runtime::new();rt.primary_numeric_access_enabled=enabled;rt.diagnostics.enabled=false;let env=rt.global_env;let array=rt.array(&[Some(Value::Number(1.0))]);rt.declare(env,"array",array).unwrap();rt.declare(env,"mode",Value::Number(mode as f64)).unwrap();rt.declare(env,"hits",Value::Number(0.0)).unwrap();let key=rt.object();let f=rt.make_closure(mutate_key,env,0,"toString");let name=rt.string("toString");rt.define_data(key,name,f,true,true,true).unwrap();let result=rt.get(array,key);match mode{0=>assert_eq!(number_bits(result.unwrap()),(-0.0f64).to_bits()),1|2=>{assert_eq!(result.unwrap(),Value::Number(91.0));assert_eq!(rt.lookup(env,"hits").unwrap(),Value::Number(1.0));},3=>assert_eq!(result.unwrap(),Value::Undefined),_=>assert!(matches!(result,Err(JsError::Throw(Value::Number(n)))if n==777.0))}}}}
#[test]fn diagnostics_still_record_original_raw_keys_once_after_coercion(){let mut rt=Runtime::new();rt.primary_numeric_access_enabled=true;rt.diagnostics.enabled=false;let env=rt.global_env;let array=rt.array(&[Some(Value::Number(-0.0))]);rt.declare(env,"array",array).unwrap();rt.declare(env,"mode",Value::Number(5.0)).unwrap();let key=rt.object();let f=rt.make_closure(mutate_key,env,0,"toString");let name=rt.string("toString");rt.define_data(key,name,f,true,true,true).unwrap();assert_eq!(number_bits(rt.get(array,key).unwrap()),(-0.0f64).to_bits());let record=rt.diagnostics.recent.back().unwrap();assert_eq!(record.receiver,array);assert!(matches!(record.key,KeyInput::Value(raw)if raw==key));let zero_records=rt.diagnostics.recent.iter().filter(|r|r.receiver==array&&matches!(r.key,KeyInput::Value(raw)if raw==key)).count();assert_eq!(zero_records,1);rt.diagnostics.recent.clear();rt.get(array,Value::Number(-0.0)).unwrap();assert!(matches!(rt.diagnostics.recent.back().unwrap().key,KeyInput::Value(Value::Number(n))if n.to_bits()==(-0.0f64).to_bits()));}
#[test]fn existing_writes_allow_readonly_length_and_nonextensibility_while_holes_and_getters_fall_back(){for enabled in[false,true]{let mut rt=Runtime::new();rt.primary_numeric_access_enabled=enabled;let array=rt.array(&[Some(Value::Number(1.0)),Some(Value::Number(2.0))]);let length=rt.string("length");rt.define_data(array,length,Value::Number(2.0),false,false,false).unwrap();let id=rt.object_id(array).unwrap();rt.objects[id.0].extensible=false;let zero=rt.string("0");rt.set(array,zero,Value::Number(-0.0),true).unwrap();assert_eq!(number_bits(rt.get(array,zero).unwrap()),(-0.0f64).to_bits());let two=rt.string("2");assert!(rt.set(array,two,Value::Number(3.0),true).is_err());let hole=rt.array(&[None]);let env=rt.global_env;rt.declare(env,"written",Value::Undefined).unwrap();let proto=rt.object();let f=rt.make_closure(setter,env,1,"setter");rt.define_accessor(proto,zero,None,Some(f),true,true).unwrap();rt.set_prototype(hole,proto).unwrap();rt.set(hole,zero,Value::Number(42.0),true).unwrap();assert_eq!(rt.lookup(env,"written").unwrap(),Value::Number(42.0));assert!(!rt.has_own_property(hole,zero).unwrap());}}
#[test]fn readonly_descriptors_and_non_numbers_deopt_without_skipping_original_set_behavior(){for enabled in[false,true]{let mut rt=Runtime::new();rt.primary_numeric_access_enabled=enabled;let array=rt.array(&[Some(Value::Number(1.0))]);let zero=rt.string("0");rt.define_data(array,zero,Value::Number(1.0),false,true,true).unwrap();assert!(rt.set(array,zero,Value::Number(9.0),true).is_err());rt.set(array,zero,Value::Number(9.0),false).unwrap();assert_eq!(rt.get(array,zero).unwrap(),Value::Number(1.0));let fresh=rt.array(&[Some(Value::Number(1.0))]);let text=rt.string("changed");rt.set(fresh,zero,text,true).unwrap();assert_eq!(rt.get(fresh,zero).unwrap(),text);let id=rt.object_id(fresh).unwrap();assert!(matches!(rt.objects[id.0].kind,ObjectKind::Array{primary_numeric:false,..}));}}
fn gc_rounds(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{let env=rt.child_env(parent);for(name,value)in[("battles",23.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(value))?;}let mut seen=std::collections::HashSet::new();let mut reused=0;for round in 0..23{let array=rt.array(&[Some(Value::Number(1.0)),Some(Value::Number(-0.0))]);let id=rt.object_id(array)?;if !seen.insert(id){reused+=1;}let zero=rt.string("0");let bits=0x7ff0000000000042+round;rt.set(array,zero,Value::Number(f64::from_bits(bits)),true)?;assert_eq!(number_bits(rt.get(array,zero)?),bits);let empty=rt.array(&[]);assert_eq!(rt.get(empty,zero)?,Value::Undefined);rt.assign(env,"battleIndex",Value::Number(round as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}assert!(reused>0);Ok(Value::Number(23.0))}
#[test]fn raw_access_does_not_leak_old_presence_or_values_across_23_actual_source_collections(){let mut rt=Runtime::new();rt.primary_numeric_access_enabled=true;rt.diagnostics.enabled=false;rt.enable_native_battle_gc();let f=rt.make_closure(gc_rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(f,&include_str!("native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();assert_eq!(rt.call(f,Value::Undefined,&[]).unwrap(),Value::Number(23.0));assert_eq!(rt.native_battle_gc_stats().collections,23);}
